import sys

data = sys.stdin.read().split()
n = int(data[0])
a = int(data[1])
left = [int(x) for x in data[2:2 + a]]
b = int(data[2 + a])
right = [int(x) for x in data[3 + a:3 + a + b]]
# doubled coordinates: every tick moves each ant by 1, so one real time unit is 2 ticks
ants = [[2 * x, -1] for x in left] + [[2 * x, 1] for x in right]
tick = 0
last = 0
while ants:
    alive = []
    for p, dr in ants:
        if (p == 0 and dr == -1) or (p == 2 * n and dr == 1):
            last = tick
        else:
            alive.append([p, dr])
    ants = alive
    for ant in ants:
        ant[0] += ant[1]
    seen = {}
    for ant in ants:
        seen.setdefault(ant[0], []).append(ant)
    for grp in seen.values():
        if len(grp) == 2:
            grp[0][1] = -grp[0][1]
            grp[1][1] = -grp[1][1]
    tick += 1
print(last // 2)

